echo "=== @playwright/mcp exists? ==="; curl -sS -m 10 https://registry.npmjs.org/@playwright%2Fmcp | python3 -c "import json,sys; d=json.load(sys.stdin); print('latest', d['dist-tags']['latest'])" 2>&1; echo "=== write global MCP config ==="; mkdir -p ~/.config/mcp && cat > ~/.config/mcp/mcp.json <<'JSON'
{
  "mcpServers": {
    "browser": {
      "command": "npx",
      "args": ["-y", "@playwright/mcp@latest", "--headless", "--isolated"]
    }
  }
}
JSON
cat ~/.config/mcp/mcp.json

